//! Cargo-driven `apphelp.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is apphelp-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x77480000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ff6d000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ff6d000000u64)),
        o => panic!("apphelp-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:delayimp_rust"],
        "x86_64" => &["engine:delayimp_rust"],
        "aarch64" => &["engine:delayimp_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("apphelp-rust")
        .c_from_compile_db("apphelp_shims", &["dll/appcompat/apphelp/rust_varargs_shim.c"])
        .resource_from_rc("dll/appcompat/apphelp/apphelp.rc", "apphelp_res")
        .spec2def("dll/appcompat/apphelp/apphelp.spec", "apphelp.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
